#[derive(Default, Clone, Debug, Collect)]
#[collect(no_drop)]
pub struct PropertyMap<'gc, V>(
    PropertyIndexMap<PropertyName<'gc>, V>,
    // Monotone possible-membership bits, not cached descriptors or misses.
    // Two u32 lanes avoid imposing a new u64 alignment on every map.
    #[collect(require_static)] [u32; 2],
);

/// Every hash, including zero, requires one nonzero bit in each lane.
/// Collisions only retain the original exact table lookup; no bit accepts a key.
#[inline]
fn property_miss_bits(hash: u64) -> [u32; 2] {
    [1u32 << ((hash as u32) & 31), 1u32 << (((hash >> 32) as u32) & 31)]
}

impl<'gc, V> PropertyMap<'gc, V> {
    pub fn new() -> Self {
        Self(PropertyIndexMap::default(), [0; 2])
    }

